/// Короткий красивый адрес портала.
///
/// Сами файлы лежат рядом с артефактами, куда уже умеет писать пользователь
/// GitHub Actions. PocketBase публикует их также по /portal/, поэтому nginx
/// и отдельный virtual host не нужны.

const WESI_PORTAL_STATIC_ROOT =
  ($os.getenv("WESI_ARTIFACTS_DIR") ||
    "/opt/pocketbase/pb_public/artifacts") + "/portal";

routerAdd("GET", "/portal", (e) => e.redirect(308, "/portal/"));

/// Страница отдаётся с запретом на «тихий» кеш.
///
/// Без заголовка `Cache-Control` браузер решает сам: по правилу эвристики он
/// считает страницу свежей примерно десятую часть времени, прошедшего с её
/// последнего изменения. Для страницы, пролежавшей сутки, это часы — и
/// человек после выкладки продолжает видеть прежнюю версию, не понимая
/// почему. Выкладка при этом прошла, файлы на диске новые, и доказать
/// обратное нечем: спор с собственным кешем выглядит как «ничего не
/// починили».
///
/// Здесь это особенно больно: стили и скрипты вклеены прямо в HTML одним
/// ответом, поэтому суффиксы вроде `?v=11` ничего не решают — кешируется
/// сама страница целиком.
///
/// `no-cache` не запрещает хранить копию, он требует каждый раз спросить
/// сервер, не изменилась ли она. Не изменилась — ответ 304 без тела, то есть
/// почти бесплатно.
routerAdd(
  "GET",
  "/portal/{path...}",
  $apis.static(WESI_PORTAL_STATIC_ROOT, true),
  (e) => {
    e.response.header().set("Cache-Control", "no-cache, must-revalidate");
    return e.next();
  },
);
